INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020015, "いかんいかん\n資材の山に埋もれて\nしまうところだった", "", "", "", "", 10, 302, 11, "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020016, "", "", "", "", "", "", 302, 91, "", 0);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020017, "nyx_302_yuni_02", 1, "", 0.2, "", 0, 302, 3, "NoItem", 2);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020018, "nyx_302_yuni_02", 1, 0.2, 0.2, "", 0, 302, 3, "nyx_idle_normal", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020019, "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", "", "", "", "", 10, 302, 11, "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020020, "", "", "", "", "", "", 302, 93, "", 5);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020021, 0, "", "", "", "", "", 302, 4, "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020022, "nyx_cmn_03", "", "", 0.2, "", 1, 302, 3, "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020023, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", "", "", "", "", 10, 302, 11, "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020024, "", "", "", "", "", "", 302, 91, "", 0);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020025, "nyx_301_yuni_01", "", "", 0.2, "", 1, 302, 3, "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020026, "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", "", "", "", "", 10, 302, 11, "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020027, 1, "", "", "", "", "", 302, 91, "", 0);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020028, "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", "", "", "", "", 10, 302, 11, "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020029, 1, "", "", "", "", "", 302, 91, "", 0);
